from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    k = len(alphabet)
    char_to_idx = {c: i for i, c in enumerate(alphabet)}

    # Build Aho-Corasick trie
    children: list[list[int]] = [[-1] * k]
    bad: list[bool] = [False]

    for word in banned:
        node = 0
        for ch in word:
            ci = char_to_idx[ch]
            if children[node][ci] == -1:
                children[node][ci] = len(children)
                children.append([-1] * k)
                bad.append(False)
            node = children[node][ci]
        bad[node] = True

    # Build failure links and complete transition table
    fail = [0] * len(children)
    go = [row[:] for row in children]
    q = deque()

    for ci in range(k):
        nxt = go[0][ci]
        if nxt != -1:
            q.append(nxt)
        else:
            go[0][ci] = 0

    while q:
        u = q.popleft()
        if bad[fail[u]]:
            bad[u] = True
        for ci in range(k):
            v = children[u][ci]
            if v != -1:
                fail[v] = go[fail[u]][ci]
                q.append(v)
            else:
                go[u][ci] = go[fail[u]][ci]

    # Map non-bad states to matrix indices
    state_to_idx = {}
    for u, is_bad in enumerate(bad):
        if not is_bad:
            state_to_idx[u] = len(state_to_idx)

    m_size = len(state_to_idx)
    mat = [[0] * m_size for _ in range(m_size)]
    for u, ui in state_to_idx.items():
        for ci in range(k):
            v = go[u][ci]
            if not bad[v]:
                mat[ui][state_to_idx[v]] += 1

    def mat_mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        res = [[0] * m_size for _ in range(m_size)]
        for i in range(m_size):
            ai = a[i]
            ri = res[i]
            for j in range(m_size):
                aij = ai[j]
                if aij:
                    bj = b[j]
                    for l in range(m_size):
                        ri[l] = (ri[l] + aij * bj[l]) % MOD
        return res

    def vec_mul(v: list[int], a: list[list[int]]) -> list[int]:
        res = [0] * m_size
        for j in range(m_size):
            vj = v[j]
            if vj:
                aj = a[j]
                for l in range(m_size):
                    res[l] = (res[l] + vj * aj[l]) % MOD
        return res

    vec = [0] * m_size
    vec[0] = 1
    exp = n
    while exp > 0:
        if exp & 1:
            vec = vec_mul(vec, mat)
        exp >>= 1
        if exp > 0:
            mat = mat_mul(mat, mat)

    return sum(vec) % MOD
